package it.frociart.app;
import android.app.*;import android.os.*;import android.text.*;import android.text.InputFilter;import android.view.*;import android.view.inputmethod.*;import android.widget.*;import java.util.*;import java.util.function.*;
final class FlowCommandPalette {
 final Ui.Sheet sheet;final EditText query;final TextView status;private final Activity owner;private final Supplier<List<FlowCommandSearch.Entry>> source;private final Predicate<FlowCommandSearch.Entry> activate;private final Handler handler=new Handler(Looper.getMainLooper());private final List<FlowCommandSearch.Entry> found=new ArrayList<>();private final List<Ui.Choice> rows=new ArrayList<>();private String filteredQuery="";private int selection;private boolean closed,chosen;
 private final Runnable filterTask=()->filter();
 FlowCommandPalette(Activity owner,Ui.Sheet sheet,Supplier<List<FlowCommandSearch.Entry>> source,Predicate<FlowCommandSearch.Entry> activate,String initial){
  this.owner=owner;this.sheet=sheet;this.source=source;this.activate=activate;query=Ui.edit(owner,initial==null?"":initial,"Riordina, variabili, Java, PDF…",false);query.setContentDescription("Comando da cercare");query.setFilters(new InputFilter[]{new InputFilter.LengthFilter(FlowCommandSearch.MAX_QUERY)});query.setSingleLine(true);query.setImeOptions(EditorInfo.IME_ACTION_SEARCH);sheet.fixed(query);status=Ui.note(owner,"");Ui.pad(status,0,8,0,10);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);sheet.fixed(status);
  query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){handler.removeCallbacks(filterTask);handler.postDelayed(filterTask,90);}public void afterTextChanged(Editable e){}});
  query.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEARCH||event!=null&&event.getKeyCode()==KeyEvent.KEYCODE_ENTER&&event.getAction()==KeyEvent.ACTION_UP){choose();return true;}return false;});
  query.setOnKeyListener((v,code,event)->{if(event.getAction()!=KeyEvent.ACTION_DOWN)return false;if(code==KeyEvent.KEYCODE_DPAD_DOWN||code==KeyEvent.KEYCODE_DPAD_UP){if(!found.isEmpty()){selection=Math.max(0,Math.min(found.size()-1,selection+(code==KeyEvent.KEYCODE_DPAD_DOWN?1:-1)));highlight();}return true;}if(code==KeyEvent.KEYCODE_ESCAPE){sheet.dismiss();return true;}return false;});filter();
 }
 void showKeyboard(){query.requestFocus();query.selectAll();handler.postDelayed(()->{if(!closed&&sheet.dialog.isShowing()){InputMethodManager ime=(InputMethodManager)owner.getSystemService(android.content.Context.INPUT_METHOD_SERVICE);if(ime!=null)ime.showSoftInput(query,InputMethodManager.SHOW_IMPLICIT);}},130);}
 private void filter(){if(closed||chosen)return;List<FlowCommandSearch.Entry> all=source.get();Map<FlowCommandSearch.Entry,Integer> ranks=new IdentityHashMap<>();String text=query.getText().toString();filteredQuery=text;for(FlowCommandSearch.Entry e:all)ranks.put(e,FlowCommandSearch.rank(text,e.label,e.path,e.aliases));all.removeIf(e->ranks.get(e)<0);all.sort(Comparator.comparingInt(e->ranks.get(e)));found.clear();found.addAll(all);selection=0;rows.clear();sheet.body.removeAllViews();status.setText(found.isEmpty()?"Nessun comando trovato. Prova un’altra parola.":found.size()+(found.size()==1?" comando":" comandi")+" · tocca per aprire");if(found.isEmpty())sheet.paragraph("Cerca una funzione nei menu: per esempio variabili, ciclo, Java o PDF.");for(int i=0;i<found.size();i++){final int index=i;FlowCommandSearch.Entry e=found.get(i);Ui.Choice row=sheet.choice(e.label,e.path+(e.enabled?"":" · Non disponibile adesso"),Ui.accentInk(),()->{selection=index;choose();});row.setEnabled(e.enabled);row.setAlpha(e.enabled?1:.5f);rows.add(row);}highlight();}
 private void highlight(){for(int i=0;i<rows.size();i++){rows.get(i).setSelected(i==selection);rows.get(i).setContentDescription(found.get(i).label+" · "+found.get(i).path+(found.get(i).enabled?"":" · Non disponibile adesso")+(i==selection?" · selezionato":""));}if(selection>=0&&selection<rows.size())sheet.scroll.smoothScrollTo(0,rows.get(selection).getTop());}
 void choose(){if(closed||chosen)return;handler.removeCallbacks(filterTask);if(!query.getText().toString().equals(filteredQuery))filter();if(found.isEmpty())return;if(selection>=found.size())selection=0;FlowCommandSearch.Entry e=found.get(selection);if(!e.enabled){status.setText("Questo comando non è disponibile adesso.");return;}chosen=true;if(!activate.test(e)){chosen=false;status.setText("Il comando non è disponibile. Riapri la ricerca se il progetto è cambiato.");}}
 void restoreSelection(int start,int end){int n=query.length();query.setSelection(Math.max(0,Math.min(start,n)),Math.max(0,Math.min(end,n)));}
 void close(){closed=true;handler.removeCallbacksAndMessages(null);}
}
